/**
 * Event Interest Functions
 */

// Get count of users interested in an event
export const getEventInterestCount = async (eventId: string): Promise<number> => {
  try {
    const { count, error } = await supabase
      .from('event_interested')
      .select('*', { count: 'exact', head: true })
      .eq('event_id', eventId);
      
    if (error) throw error;
    return count || 0;
  } catch (error) {
    console.error('Error getting interest count:', error);
    return 0;
  }
};

// Check if a user is interested in an event
export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { data, error } = await supabase
      .from('event_interested')
      .select('*')
      .eq('event_id', eventId)
      .eq('user_id', userId)
      .maybeSingle();
      
    if (error) throw error;
    return !!data;
  } catch (error) {
    console.error('Error checking user interest:', error);
    return false;
  }
};

// Mark a user as interested in an event
