/**
 * Event Attendance Functions
 */

// Check in a user to an event
export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('event_attendees_new')
      .insert({
        event_id: eventId,
        user_id: userId,
      });
      
    if (error) throw error;
    
    // Update user's attended events count
    await supabase.rpc('increment_user_attended_events', { user_id: userId });
    
    return true;
  } catch (error) {
    console.error('Error checking in user:', error);
    return false;
  }
};

